// scripts/sequence-page-bundle.mjs — the esbuild recipe for the Schedule page bundle (public/sequence/page.js).
// No shebang, no side effects: vite.config.js imports it (dev serves the bundle fresh on every request), the CLI
// (scripts/build-sequence-page.mjs) and test/sequencePageBundle.test.js import it too, so all three build the same bytes.
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";
import { buildSync } from "esbuild";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const ENTRY = resolve(ROOT, "src/workspaces/scheduler/page/main.jsx");
export const OUT = resolve(ROOT, "public/sequence/page.js");
const BANNER = "/* GENERATED by scripts/build-sequence-page.mjs from src/workspaces/scheduler/page/* and src/shared/schedule/* — do not edit; run `npm run build:sequence-page`. */\n";

export function buildPage() {
  const r = buildSync({
    entryPoints: [ENTRY], bundle: true, write: false, format: "iife", target: "es2020",
    jsx: "transform", jsxFactory: "React.createElement", jsxFragment: "React.Fragment",
    loader: { ".js": "jsx", ".jsx": "jsx" },
    legalComments: "none", charset: "utf8", logLevel: "silent", absWorkingDir: ROOT,
  });
  return BANNER + r.outputFiles[0].text;
}
